-- 3. Populate Authors (15 bilingual authors)
INSERT INTO `authors` (`id`, `slug`, `name_en`, `name_ur`, `bio_en`, `bio_ur`) VALUES
(1, 'mumtaz-mufti', 'Mumtaz Mufti', 'ممتاز مفتی', 'Mumtaz Mufti was a renowned Urdu writer. He wrote short stories, novels, autobiographies and travelogues, showcasing psychological depths.', 'ممتاز مفتی اردو کے نامور افسانہ نگار، سوانح نگار اور ناول نویس تھے۔ ان کی تحریروں میں نفسیاتی گہرائیاں نمایاں ہوتی ہیں۔'),
(2, 'bano-qudsia', 'Bano Qudsia', 'بانو قدسیہ', 'Bano Qudsia was a legendary writer and playwright best known for her landmark novel Raja Gidh.', 'بانو قدسیہ اردو ادب کی ایک نامور مصنفہ، ڈرامہ نگار اور ناول نگار تھیں، جن کا ناول راجہ گدھ ان کی پہچان بنا۔'),
(3, 'ashfaq-ahmed', 'Ashfaq Ahmed', 'اشفاق احمد', 'Ashfaq Ahmed was a legendary intellectual, writer, and broadcaster known for Zavia and his spiritual stories.', 'اشفاق احمد اردو کے عظیم دانشور، مصنف، ڈرامہ نویس اور براڈکاسٹر تھے، جو اپنے پروگرام زاویہ سے مقبول ہوئے۔'),
(4, 'quratulain-hyder', 'Quratulain Hyder', 'قرۃ العین حیدر', 'Quratulain Hyder was an influential novelist, best known for Aag Ka Darya (River of Fire).', 'قرۃ العین حیدر اردو ادب کی صف اول کی ناول نگار تھیں، جو اپنے معرکہ آرا ناول آگ کا دریا کے لیے جانی جاتی ہیں۔'),
(5, 'intizar-hussain', 'Intizar Hussain', 'انتظار حسین', 'Intizar Hussain was a legendary short story writer and novelist, known for Basti.', 'انتظار حسین اردو کے ایک مایہ ناز افسانہ نگار اور ناول نگار تھے، جن کا ناول بستی عالمی شہرت کا حامل ہے۔'),
(6, 'ibn-e-safi', 'Ibn-e-Safi', 'ابنِ صفی', 'Ibn-e-Safi was the creator of Jasoosi Dunya and Imran Series, the legendary detective fiction writer.', 'ابنِ صفی اردو کے سب سے مشہور جاسوسی ناول نگار تھے، جنہوں نے جاسوسی دنیا اور عمران سیریز تخلیق کی۔'),
(7, 'naseem-hijazi', 'Naseem Hijazi', 'نسیم حجازی', 'Naseem Hijazi was a highly popular historical fiction writer who wrote epic Islamic history novels.', 'نسیم حجازی اردو کے مشہور تاریخی ناول نگار تھے، جنہوں نے اسلامی تاریخ پر مبنی متعدد شاہکار تخلیق کیے۔'),
(8, 'mustansar-hussain-tarar', 'Mustansar Hussain Tarar', 'مستنصر حسین تارڑ', 'Mustansar Hussain Tarar is a legendary travelogue writer, novelist, and television host.', 'مستنصر حسین تارڑ اردو کے سب سے مقبول سفرنامہ نگار، ناول نگار اور ٹی وی ہوسٹ ہیں۔'),
(9, 'saadat-hasan-manto', 'Saadat Hasan Manto', 'سعادت حسن منٹو', 'Saadat Hasan Manto was a revolutionary short story writer, best known for his bold and realistic depiction of society.', 'سعادت حسن منٹو اردو کے ایک انقلابی افسانہ نگار تھے، جو معاشرے کے تلخ سچ کو بے باکی سے لکھنے کے لیے مشہور ہیں۔'),
(10, 'ismat-chughtai', 'Ismat Chughtai', 'عصمت چغتائی', 'Ismat Chughtai was an eminent Urdu writer known for her fierce feminist voice and progressive literature.', 'عصمت چغتائی اردو کی ایک ممتاز ترقی پسند مصنفہ تھیں جو اپنی بے باک نسوانی آواز اور کہانیوں کے لیے جانی جاتی ہیں۔'),
(11, 'allama-iqbal', 'Allama Muhammad Iqbal', 'علامہ محمد اقبال', 'Allama Iqbal, the national poet of Pakistan, was a philosopher, poet and politician of British India.', 'حکیم الامت علامہ محمد اقبال پاکستان کے قومی شاعر، عظیم فلسفی اور مفکرِ اسلام ہیں۔'),
(12, 'fyodor-dostoevsky', 'Fyodor Dostoevsky', 'فیودر دوستوفسکی', 'Fyodor Dostoevsky was a world-famous Russian novelist, author of Crime and Punishment.', 'فیودر دوستوفسکی عالمی شہرت یافتہ روسی ناول نگار تھے، جو جرم و سزا جیسے لافانی ناول کے خالق ہیں۔'),
(13, 'leo-tolstoy', 'Leo Tolstoy', 'لیو ٹالسٹائے', 'Leo Tolstoy was a legendary Russian writer, known for War and Peace and Anna Karenina.', 'لیو ٹالسٹائے روس کے عظیم ترین مصنفین میں سے ایک ہیں، جو اینا کرینینا کے مصنف ہیں۔'),
(14, 'paulo-coelho', 'Paulo Coelho', 'پاؤلو کوئلو', 'Paulo Coelho is a world-renowned Brazilian author best known for his spiritual guide novel, The Alchemist.', 'پاؤلو کوئلو برازیل کے مشہور ناول نگار ہیں جن کا ناول دی الکیمسٹ دنیا بھر میں مقبول ہے۔'),
(15, 'patras-bokhari', 'Patras Bokhari', 'پطرس بخاری', 'Patras Bokhari was a brilliant humorist, educator, and diplomat in British India and Pakistan.', 'پطرس بخاری اردو کے مایہ ناز مزاح نگار، ماہرِ تعلیم اور سفارت کار تھے۔');

