INSERT INTO `books` (`id`, `slug`, `sku`, `isbn`, `title_en`, `title_ur`, `subtitle_en`, `subtitle_ur`, `author_id`, `publisher_id`, `category_id`, `language`, `description_en`, `description_ur`, `pages`, `weight_grams`, `binding`, `year_published`, `price_gbp`, `price_pkr`, `discount_percent`, `stock_quantity`, `is_new_arrival`, `is_featured`, `is_active`, `cover_image`, `inside_preview_pdf`, `loc_classification`, `marc_record`) VALUES
-- Novel
(1, 'aab-e-gum', 'NOV-AAB-001', '9789693507361', 'Aab-e-Gum', 'آبِ گم', 'Memories and Humour', 'یادوں اور خاکوں کا مجموعہ', 1, 1, 1, 'Urdu', 
'A classic satirical work by Mumtaz Mufti, full of cultural sketches and psychological observations.', 
'ممتاز مفتی کی ایک شاہکار تصنیف جو طنز و مزاح، یادوں اور معاشرتی خاکوں پر مشتمل ہے۔', 412, 450, 'Hardback', 2005, 14.99, 5396.00, 15, 25, 1, 1, 1, NULL, NULL, 'PK2200.M8 A23', '00000cam a2200301 a 4500 001 u-001 020  $a9789693507361 100  $aMufti, Mumtaz 245  $aAab-e-Gum'),
(2, 'udaas-naslein', 'NOV-UDA-002', '9789693507422', 'Udaas Naslein', 'اداس نسلیں', 'The Weary Generations', 'صدیوں کی پیاس اور اداسی', 5, 1, 1, 'Urdu', 
'Abdullah Hussein\'s masterpiece novel reflecting the generation that witnessed the partition of India.', 
'عبداللہ حسین کا معرکہ آرا ناول جو تقسیمِ ہند کے دور اور اس کے خونی حالات کو پیش کرتا ہے۔', 650, 680, 'Hardback', 2011, 19.99, 7196.00, 20, 15, 1, 1, 1, NULL, NULL, 'PK2200.H87 U3', '00000cam a2200301 a 4500 001 u-002 020  $a9789693507422 100  $aHussein, Abdullah 245  $aUdaas Naslein'),
(3, 'raja-gidh', 'NOV-RAJ-003', '9789693504889', 'Raja Gidh', 'راجہ گدھ', 'The Vulture King', 'حرام و حلال کی نفسیاتی جنگ', 2, 1, 1, 'Urdu', 
'A highly acclaimed novel by Bano Qudsia exploring the theme of halal and haram, and human desires.', 
'بانو قدسیہ کا ایک بے مثال ناول جو انسانی جبلتوں، محبت اور حلال و حرام کی نفسیات کا احاطہ کرتا ہے۔', 540, 520, 'Hardback', 1981, 16.50, 5940.00, 10, 30, 0, 1, 1, NULL, NULL, 'PK2200.Q8 R3', '00000cam a2200301 a 4500 001 u-003 020  $a9789693504889 100  $aQudsia, Bano 245  $aRaja Gidh'),
(4, 'aag-ka-darya', 'NOV-AAG-004', '9789693510521', 'Aag Ka Darya', 'آگ کا دریا', 'River of Fire', 'برصغیر کی تاریخ کا لافانی سفر', 4, 3, 1, 'Urdu', 
'An epic socio-historical novel by Quratulain Hyder spanning thousands of years of Indian subcontinent history.', 
'قرۃ العین حیدر کا لکھا ہوا عظیم ترین تاریخی ناول جو اڑھائی ہزار سالہ تاریخ پر محیط ہے۔', 800, 850, 'Hardback', 1959, 24.99, 8996.00, 30, 10, 0, 1, 1, NULL, NULL, 'PK2200.H9 A2', '00000cam a2200301 a 4500 001 u-004 020  $a9789693510521 100  $aHyder, Quratulain 245  $aAag Ka Darya'),
(5, 'khuda-ki-basti', 'NOV-KHU-005', '9789693522101', 'Khuda Ki Basti', 'خدا کی بستی', 'God\'s Colony', 'معاشرتی پسماندگی اور جدوجہد', 5, 3, 1, 'Urdu', 
'Shaukat Siddiqui\'s landmark realistic novel depicting post-partition poverty and social degradation.', 
'شوکت صدیقی کا تحریر کردہ لافانی ناول جو آزادی کے بعد کے کچی آبادیوں کے مسائل کا نقشہ کھینچتا ہے۔', 480, 460, 'Paperback', 2015, 9.99, 3596.00, 0, 40, 1, 0, 1, NULL, NULL, 'PK2200.S5 K5', '00000cam a2200301 a 4500 001 u-005 020  $a9789693522101 100  $aSiddiqui, Shaukat 245  $aKhuda Ki Basti'),
(6, 'aangan', 'NOV-AAN-006', '9789693502231', 'Aangan', 'آنگن', 'The Courtyard', 'ایک گھرانے کی تقسیم کی داستان', 10, 1, 1, 'Urdu', 
'A majestic psychological novel by Khadija Mastoor setting domestic struggles during freedom struggle.', 
'خدیجہ مستور کا شاہکار ناول جس میں آزادی کی تحریک کے پس منظر میں ایک خاندان کے اندرونی حالات کو دکھایا گیا ہے۔', 380, 400, 'Hardback', 2012, 12.00, 4320.00, 15, 18, 0, 0, 1, NULL, NULL, 'PK2200.M3 A2', '00000cam a2200301 a 4500 001 u-006 020  $a9789693502231 100  $aMastoor, Khadija 245  $aAangan'),
(7, 'alipur-ka-eli', 'NOV-ALI-007', '9789693501246', 'Alipur Ka Eli', 'علی پور کا ایلی', 'Eli of Alipur', 'ایک انسان کی اندرونی الجھنوں کی کہانی', 1, 1, 1, 'Urdu', 
'A monumental autobiographical novel by Mumtaz Mufti exploring human psychology and family taboos.', 
'ممتاز مفتی کا عظیم ترین سوانحی ناول جو انسانی نفسیات اور خاندانی بندشوں کی عکاسی کرتا ہے۔', 1100, 1200, 'Hardback', 2008, 22.50, 8100.00, 25, 8, 0, 1, 1, NULL, NULL, 'PK2200.M8 A3', '00000cam a2200301 a 4500 001 u-007 020  $a9789693501246 100  $aMufti, Mumtaz 245  $aAlipur Ka Eli'),
(8, 'bano', 'NOV-BAN-008', '9789694121289', 'Bano', 'بانو', 'The Victim of Partition', 'تقسیم کے خونی طوفان کی داستان', 2, 2, 1, 'Urdu', 
'Razia Butt\'s epic historical novel of the Partition which inspired the hit drama Dastaan.', 
'رضیہ بٹ کا تاریخی سوانحی ناول جو تقسیمِ ہند کے کربناک سانحات اور بانو نامی لڑکی کی قربانیوں پر مبنی ہے۔', 520, 500, 'Hardback', 1999, 11.99, 4316.00, 10, 22, 1, 0, 1, NULL, NULL, 'PK2200.B8 B3', '00000cam a2200301 a 4500 001 u-008 020  $a9789694121289 100  $aButt, Razia 245  $aBano'),
-- Historical Novels
(9, 'muhammad-bin-qasim', 'NOV-MBQ-009', '9789693005512', 'Muhammad Bin Qasim', 'محمد بن قاسم', 'Conquest of Sindh', 'سندھ کی فتح کی تاریخی داستان', 7, 5, 17, 'Urdu', 
