(10, 'akhri-chattan', 'NOV-AKH-010', '9789693005529', 'Akhri Chattan', 'آخری چٹان', 'The Last Rock', 'تاتاریوں کے خلاف عالمِ اسلام کی جنگ', 7, 5, 17, 'Urdu', 
